<?php
declare(strict_types=1);require_once __DIR__.'/env.php';require_once __DIR__.'/phone.php';
function send_sms(string $to,string $message,array $opts=[]): array { if(!env_bool('SMS_ENABLED'))return ['ok'=>false,'disabled'=>true,'error'=>'SMS disabled'];$phone=normalize_ph_phone($to);$key=(string)env_value('SEMAPHORE_API_KEY','');if(!$phone||$key==='')return ['ok'=>false,'error'=>'SMS configuration is unavailable'];$fields=['apikey'=>$key,'number'=>$phone,'message'=>$message];$sender=trim((string)env_value('SEMAPHORE_SENDER_NAME',''));if($sender!=='')$fields['sendername']=$sender;$ch=curl_init('https://api.semaphore.co/api/v4/messages');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$fields,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_SSL_VERIFYPEER=>true]);$raw=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);$data=json_decode((string)$raw,true);return ['ok'=>$http>=200&&$http<300,'status_code'=>$http,'response'=>$data,'error'=>$err?:null]; }
